import { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { CheckCircle2 } from "lucide-react";

const positionClasses = {
  "bottom-center": "bottom-4 left-1/2 -translate-x-1/2",
  "bottom-right": "bottom-4 right-4",
  "top-center": "top-4 left-1/2 -translate-x-1/2",
  "top-right": "top-4 right-4",
} as const;

interface ToastProps {
  position?: keyof typeof positionClasses;
  duration?: number;
  color?: string;
  title?: string;
  message?: string;
}

export default function Toast({
  position = "bottom-center",
  duration = 3,
  color = "#0071e3",
  title = "Guardado correctamente",
  message = "Tus cambios ya están aplicados.",
}: ToastProps) {
  const [items, setItems] = useState<{ id: number }[]>([]);
  const fromTop = position.startsWith("top");

  const fire = () => {
    const id = Date.now();
    setItems((p) => [...p, { id }]);
    setTimeout(() => setItems((p) => p.filter((i) => i.id !== id)), duration * 1000);
  };

  return (
    <div className="relative flex h-72 w-full items-center justify-center">
      <button
        type="button"
        onClick={fire}
        className="rounded-full px-5 py-2.5 text-sm font-semibold text-white"
        style={{ backgroundColor: color }}
      >
        Disparar notificación
      </button>
      <div
        className={`absolute z-10 flex w-64 max-w-[calc(100%-2rem)] flex-col gap-2 ${positionClasses[position]}`}
      >
        <AnimatePresence>
          {items.map((i) => (
            <motion.div
              key={i.id}
              role="status"
              initial={{ opacity: 0, y: fromTop ? -24 : 24, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: fromTop ? -16 : 16, scale: 0.95 }}
              transition={{ type: "spring", stiffness: 380, damping: 28 }}
              className="flex w-full items-start gap-3 rounded-xl border border-black/10 bg-white p-3.5 text-[#1d1d1f] shadow-[0_4px_12px_rgba(0,0,0,0.04),0_24px_60px_rgba(0,0,0,0.1)] dark:border-white/10 dark:bg-[#1d1d1f] dark:text-[#f5f5f7]"
            >
              <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" style={{ color }} />
              <div>
                <p className="text-sm font-medium">{title}</p>
                <p className="mt-0.5 text-xs text-[#86868b]">{message}</p>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </div>
  );
}

css:
.uv-zs {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-zs {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  position: relative;
  width: 20em;
  height: 14em;
  font-size: var(--s);
}

.uv-zs>.fire {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  padding: .8em 1.25em;
  border: 0;
  border-radius: 999px;
  font: inherit;
  font-weight: 600;
  color: #fff;
  background: var(--c1);
  cursor: pointer;
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-zs>.fire:active {
  transform: scale(.94);
}

.uv-zs .toast {
  position: absolute;
  z-index: 2;
  left: 50%;
  bottom: .5em;
  display: flex;
  align-items: center;
  gap: .75em;
  width: 18em;
  padding: .85em;
  border-radius: 1em;
  color: var(--fg);
  background: var(--bg);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 18px 45px rgba(0,0,0,.18);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%,3em) scale(.82);
}

.uv-zs .toast i {
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
  font-style: normal;
  color: #fff;
  background: #30a46c;
}

.uv-zs .toast span {
  display: grid;
  gap: .15em;
}

.uv-zs .toast small {
  opacity: .5;
}

.uv-zs .toast.show {
  animation: uv-zs calc(3.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

@keyframes uv-zs {
  0% {
    opacity: 0;
    transform: translate(-50%,3em) scale(.82);
  }
  12%,82% {
    opacity: 1;
    transform: translate(-50%,0) scale(1);
    pointer-events: auto;
  }
  100% {
    opacity: 0;
    transform: translate(-50%,1.5em) scale(.92);
  }
}

