function setup(el: any) {
  const b=el.querySelector(".fire"),t=el.querySelector(".toast"),bar=t.querySelector("em"),n=t.querySelector("strong"),s=t.querySelector("small");let timer;b.addEventListener("click",()=>{clearInterval(timer);let p=0;t.classList.add("show");bar.style.setProperty("--p","0%");n.textContent="0%";s.textContent="Preparando…";timer=setInterval(()=>{p=Math.min(100,p+4);bar.style.setProperty("--p",p+"%");n.textContent=p+"%";s.textContent=p===100?"Subida completada":"Subiendo…";if(p===100){clearInterval(timer);setTimeout(()=>t.classList.remove("show"),1000)}},90)})
}

