.uv-qai {
  --c1: #8b5cf6;
  --c2: #06b6d4;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --wait: 2.6;
  /* duración */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

@property --uv-qai {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.uv-qai {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 21em;
  height: 15em;
}

.uv-qai .fire {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  left: 50%;
  top: 1.2em;
  translate: -50% 0;
  padding: .6em 1.1em;
  border-radius: 2em;
  font-size: .82em;
  font-weight: 650;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-qai .fire:focus-visible,.uv-qai .vw:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-qai .tt {
  position: absolute;
  left: 50%;
  bottom: 1em;
  width: 19em;
  border-radius: 1.1em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.2em 2.4em -1em rgba(0,0,0,.45);
  transform: translate(-50%,130%) scale(.9);
  opacity: 0;
  filter: blur(4px);
  transition: transform calc(0.55s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),filter calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
  display: flex;
  align-items: center;
  gap: .75em;
  padding: .8em .9em;
  isolation: isolate;
}

.uv-qai .tt.in {
  transform: translate(-50%,0) scale(1);
  opacity: 1;
  filter: none;
}

.uv-qai .tt::before {
  content: "";
  position: absolute;
  inset: -1.5px;
  z-index: -1;
  border-radius: inherit;
  padding: 1.5px;
  background: conic-gradient(from var(--uv-qai),var(--c1),var(--c2),transparent 40%,var(--c1));
  -webkit-mask: linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: uv-qai calc(2s / var(--k)) linear infinite;
  transition: opacity calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-qai .ic {
  position: relative;
  display: grid;
  place-items: center;
  flex: none;
  width: 2.4em;
  height: 2.4em;
  border-radius: .8em;
  color: #fff;
  background: linear-gradient(135deg,var(--c1),var(--c2));
}

.uv-qai .ic>span {
  grid-area: 1/1;
  display: grid;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-qai .ic svg {
  width: 1.3em;
  height: 1.3em;
}

.uv-qai .sp svg {
  animation: uv-qai-p calc(1.4s / var(--k)) ease-in-out infinite;
}

.uv-qai .ck {
  opacity: 0;
  transform: scale(.4);
}

.uv-qai .tx {
  display: grid;
  flex: 1;
  gap: .1em;
}

.uv-qai .tx b {
  grid-area: 1/1;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-qai .w {
  background: linear-gradient(90deg,var(--fg) 35%,var(--c1) 50%,var(--fg) 65%) 0 0/250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: uv-qai-s calc(1.6s / var(--k)) linear infinite;
}

.uv-qai .d {
  opacity: 0;
}

.uv-qai small {
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-qai .vw {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .5em .9em;
  border-radius: 2em;
  font-size: .8em;
  font-weight: 700;
  color: #fff;
  background: var(--fg);
  opacity: 0;
  transform: scale(.8);
  pointer-events: none;
  transition: all calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-qai .tt.done::before {
  opacity: 0;
}

.uv-qai .tt.done .sp {
  opacity: 0;
  transform: scale(.4);
}

.uv-qai .tt.done .ck {
  opacity: 1;
  transform: none;
}

.uv-qai .tt.done .w {
  opacity: 0;
}

.uv-qai .tt.done .d {
  opacity: 1;
}

.uv-qai .tt.done .vw {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

@keyframes uv-qai {
  to {
    --uv-qai: 360deg;
  }
}

@keyframes uv-qai-s {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -150% 0;
  }
}

@keyframes uv-qai-p {
  50% {
    transform: scale(.8) rotate(20deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-qai,.uv-qai *,.uv-qai *::before,.uv-qai *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

