  left: 50%;
  top: 2.25em;
  width: 5.6em;
  height: 3.4em;
  translate: -50% 0;
  border-radius: 45%;
}

.uvq09-ftn .ck:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq09-ftn .tt.in:not(.op) .ck {
  animation: uvq09-ftn-w calc(2.6s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(1s / var(--k)) infinite;
}

.uvq09-ftn .h1,.uvq09-ftn .h2 {
  position: absolute;
  top: .5em;
  width: 2.85em;
  height: 2.2em;
