  transition: transform calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq09-ftn .h1 {
  left: 0;
  transform-origin: 100% 70%;
}

.uvq09-ftn .h2 {
  right: 0;
  transform-origin: 0 70%;
}

.uvq09-ftn .h2 svg {
  scale: -1 1;
}

.uvq09-ftn .ck svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq09-ftn .lo {
  fill: color-mix(in srgb,var(--c1) 70%,#fbbf24);
}

.uvq09-ftn .fo {
  fill: color-mix(in srgb,var(--c1) 75%,#7c2d12);
}

.uvq09-ftn .hl {
  fill: none;
  stroke: #fff3c9;
  stroke-width: 3;
  stroke-linecap: round;
  opacity: .65;
