}

.uvq09-ftn .tt.op .h2 {
  transform: translate(5.2em,.5em) rotate(30deg);
}

.uvq09-ftn .cr {
  position: absolute;
  left: 50%;
  top: 50%;
}

.uvq09-ftn .cr i {
  position: absolute;
  width: .26em;
  height: .26em;
  border-radius: 40%;
  background: color-mix(in srgb,var(--c1) 60%,#fbbf24);
  opacity: 0;
}

.uvq09-ftn .tt.op .cr i {
  animation: uvq09-ftn-c calc(0.8s / var(--k)) cubic-bezier(.25,.1,.25,1) forwards;
}

.uvq09-ftn .sl {
  position: absolute;
  left: 50%;
  top: 2.85em;
  z-index: 1;
  width: 13em;
  margin: 0;
  padding: .5em .7em;
  translate: -50% 0;
  color: var(--c2);
  background: #fffdf7;
  box-shadow: 0 .15em .4em rgba(0,0,0,.2);
  visibility: hidden;
  opacity: 0;
  transform: scaleX(.05);
  transition: transform calc(0.6s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),visibility 0s calc(0.6s / var(--k));
}

.uvq09-ftn .sl span {
  display: block;
  font: 600 .84em/1.3 Georgia,"Times New Roman",serif;
}

.uvq09-ftn .sl small {
  display: block;
  margin-top: .3em;
  font: 600 .62em/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  color: #78716c;
}

.uvq09-ftn .tt.op .sl {
  visibility: visible;
  opacity: 1;
  transform: none;
  transition: transform calc(0.6s / var(--k)) cubic-bezier(.22,1,.36,1) calc(0.15s / var(--k)),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(0.15s / var(--k)),visibility 0s;
}

.uvq09-ftn .hn {
  position: absolute;
  left: 0;
  right: 0;
  bottom: .85em;
  font-size: .7em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq09-ftn .tt.op .hn {
  opacity: 0;
}

@keyframes uvq09-ftn-w {
  0%,62%,100% {
    rotate: 0deg;
  }
  70% {
    rotate: -7deg;
  }
  78% {
    rotate: 6deg;
  }
  86% {
    rotate: -3deg;
  }
  93% {
    rotate: 1deg;
  }
}

@keyframes uvq09-ftn-c {
  0% {
    opacity: 1;
    transform: none;
  }
  100% {
    opacity: 0;
    transform: translate(var(--x),var(--y)) rotate(160deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq09-ftn,.uvq09-ftn *,.uvq09-ftn *::before,.uvq09-ftn *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

