  scale: .96;
}

.uvq09-air .fire:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq09-air .tt {
  position: absolute;
  left: 50%;
  bottom: 1em;
  width: 19em;
