document.querySelectorAll(".uvq09-air").forEach(el => {
  const t=el.querySelector(".tt"),f=el.querySelector(".fire");let tm=[];const clr=()=>{tm.forEach(clearTimeout);tm=[]};const later=(fn,ms)=>tm.push(setTimeout(fn,ms));
const show=()=>{clr();t.classList.remove("in","out");void t.offsetWidth;later(()=>{t.classList.add("in");start()},60)};
const hide=()=>{t.classList.remove("in");t.classList.add("out")};f.addEventListener("click",show);show();const tk=t.querySelector(".tm"),vw=t.querySelector(".vw");let iv=0,s=0,v=0;
const p2=n=>String(n).padStart(2,"0");const tick=()=>{s++;v+=Math.round(Math.random()*120+40);tk.textContent=p2(Math.floor(s/60))+":"+p2(s%60);vw.textContent=v.toLocaleString(document.documentElement.lang||undefined)};
const start=()=>{clearInterval(iv);s=0;v=0;tk.textContent="00:00";vw.textContent="0";t.classList.remove("off");iv=setInterval(tick,1000)};
t.querySelector(".end").addEventListener("click",()=>{clearInterval(iv);t.classList.add("off");later(hide,900)});return()=>{clr();clearInterval(iv)}
});

